from __future__ import annotations
import math


def certified_absorption_threshold(degree: int, q: float, q_prime: float) -> int:
    """Return N such that k^degree <= (q_prime/q)^k for every k >= N."""
    if degree < 0 or not 0.0 < q < q_prime < 1.0:
        raise ValueError("require degree >= 0 and 0 < q < q_prime < 1")
    if degree == 0:
        return 1
    rate = math.log(q_prime / q)
    lo = max(1, math.ceil(degree / rate))

    def margin(k: int) -> float:
        return k * rate - degree * math.log(k)

    if margin(lo) >= 0.0:
        return lo
    hi = lo
    while margin(hi) < 0.0:
        hi *= 2
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if margin(mid) >= 0.0:
            hi = mid
        else:
            lo = mid
    return hi
